<?php
/** v1.19 project decision validation and risk reminder policies (no DB). */
declare(strict_types=1);
require_once __DIR__.'/../includes/project_decisions.php';
require_once __DIR__.'/../includes/risk_reminders.php';
require_once __DIR__.'/../includes/csv.php';
$count=0;$check=static function(bool $ok,string $why)use(&$count):void{$count++;if(!$ok)throw new RuntimeException('FAIL '.$why);};
$bad=static function(callable $fn):bool {try{$fn();return false;}catch(InvalidArgumentException){return true;}};
$proposal=['title'=>'Choose hosting region','context'=>'We need a reliable region for EU customer data.','outcome'=>'','review_date'=>'2026-12-01'];
$f=taskflow_decision_fields([...$proposal,'status'=>'approved','owner_id'=>'4'],false);
$check($f['status']==='proposed'&&$f['owner_id']===null,'member cannot approve or assign an owner');
$f=taskflow_decision_fields([...$proposal,'status'=>'approved','outcome'=>'Use EU-West region','owner_id'=>'4'],true);
$check($f['status']==='approved' && $f['owner_id']===4,'manager approves with outcome and owner');
$check($bad(fn()=>taskflow_decision_fields([...$proposal,'status'=>'approved'],true)),'approval needs recorded outcome');
foreach(['invalid','APPROVED',null,[]] as $status) $check($bad(fn()=>taskflow_decision_fields([...$proposal,'status'=>$status],true)),'status enum enforced');
foreach(['',"ok\0bad",str_repeat('x',161),42,[],"bad\x7f"] as $title) $check($bad(fn()=>taskflow_decision_fields([...$proposal,'title'=>$title],false)),'title input validated');
foreach(['',"text\x1f",str_repeat('a',4001),[],false] as $context) $check($bad(fn()=>taskflow_decision_fields([...$proposal,'context'=>$context],false)),'context input validated');
foreach(["bad\x00",str_repeat('a',4001),[],false] as $outcome) $check($bad(fn()=>taskflow_decision_fields([...$proposal,'outcome'=>$outcome],false)),'outcome input validated');
foreach(['2026-02-30','2026-1-1','2199-01-01',[],"2026-01-01\0"] as $date) $check($bad(fn()=>taskflow_decision_fields([...$proposal,'review_date'=>$date],false)),'date validation');
$check(taskflow_decision_filter('')===null && taskflow_decision_filter('approved')==='approved','filter allowlist');
$check($bad(fn()=>taskflow_decision_filter('all')),'unknown filter rejected');
$check(taskflow_risk_reminder_kind('2026-12-01','2026-12-01')==='due_today','risk due date alert');
$check(taskflow_risk_reminder_kind('2026-12-02','2026-12-01')==='overdue','risk next-day-overdue alert');
$check(taskflow_risk_reminder_kind('2026-12-04','2026-12-01')===null,'no indefinite overdue spam');
$check(taskflow_risk_reminder_eligible(3,3,false,'low'),'owner receives risk alert');
$check(!taskflow_risk_reminder_eligible(2,3,true,'medium'),'noncritical with owner excludes managers');
$check(taskflow_risk_reminder_eligible(2,3,true,'critical'),'critical issue escalates to managers');
$check(taskflow_risk_reminder_eligible(2,null,true,'low'),'unowned risk alerts manager');
$check(!taskflow_risk_reminder_eligible(2,null,false,'critical'),'unowned risk not broadcast to members');
$check(str_starts_with(taskflow_csv_safe('=IMPORTXML("x")'),"'="),'decision CSV formula safe');
echo "All $count TaskFlow project-decision and risk-review checks passed.\n";
